import { Component, computed, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatRippleModule } from '@angular/material/core';
import { MatSliderModule } from '@angular/material/slider';
import {
    BindingDirective,
    IconComponent,
    TranslatePipe,
} from '@placeos/components';
import { ControlStateService } from './control-state.service';
import { DurationPipe } from './ui/duration.pipe';

@Component({
    selector: 'control-status-bar',
    template: `
        @if (capture_mod()) {
            <div
                recording
                class="divide-base-200 text-base-content flex items-center divide-x text-xs"
            >
                <div hidden>
                    <i
                        binding
                        [(model)]="rec_status"
                        [sys]="id"
                        [mod]="capture_mod()?.mod"
                        bind="status"
                    ></i>
                    <i
                        binding
                        [(model)]="rec_title"
                        [sys]="id"
                        [mod]="capture_mod()?.mod"
                        bind="title"
                    ></i>
                    <i
                        binding
                        [(model)]="rec_remaining"
                        [sys]="id"
                        [mod]="capture_mod()?.mod"
                        bind="remaining"
                    ></i>
                    <i
                        binding
                        [(model)]="rec_next"
                        [sys]="id"
                        [mod]="capture_mod()?.mod"
                        bind="next"
                    ></i>
                </div>
                <div
                    class="flex h-12 w-24 items-center justify-center p-2 text-center"
                >
                    {{ rec_title || '~Unnamed Recording~' }}
                </div>
                <div class="flex h-12 w-12 items-center justify-center">
                    <button
                        place-action="stop"
                        icon
                        matRipple
                        class="rounded-none"
                        [disabled]="!rec_status || rec_status === 'stopped'"
                        binding
                        [sys]="id"
                        [mod]="capture_mod()?.mod"
                        onEvent="click"
                        exec="stop"
                    >
                        <icon>stop</icon>
                    </button>
                </div>
                <div class="flex h-12 w-12 items-center justify-center">
                    <button
                        [attr.place-action]="
                            rec_status === 'playing' ? 'pause' : 'start'
                        "
                        icon
                        matRipple
                        class="rounded-none"
                        binding
                        [sys]="id"
                        [mod]="capture_mod()?.mod"
                        onEvent="click"
                        [exec]="rec_status === 'playing' ? 'pause' : 'start'"
                    >
                        <icon>{{
                            rec_status === 'playing' ? 'pause' : 'play_arrow'
                        }}</icon>
                    </button>
                </div>
                <div class="flex h-12 w-32 flex-col p-2">
                    <div
                        class="rounded-sm p-2 text-center uppercase"
                        [class.bg-error]="rec_status === 'playing'"
                        [class.text-error-content]="rec_status === 'playing'"
                        [class.bg-warning]="rec_status === 'paused'"
                        [class.text-warning-content]="rec_status === 'paused'"
                        [class.bg-base-300]="rec_status === 'stopped'"
                    >
                        {{
                            (rec_status === 'playing'
                                ? 'APP.CONTROL.STATE_RECORDING'
                                : rec_status === 'paused'
                                  ? 'APP.CONTROL.STATE_PAUSED'
                                  : 'APP.CONTROL.STATE_IDLE'
                            ) | translate
                        }}
                    </div>
                </div>
                <div class="h-12 p-2">
                    <label>{{ 'APP.CONTROL.REMAINING' | translate }}</label>
                    <div class="">{{ rec_remaining | duration }}</div>
                </div>
                <div class="h-12 p-2">
                    <label>{{
                        'APP.CONTROL.NEXT_RECORDING' | translate
                    }}</label>
                    <div class="">{{ rec_next | duration }}</div>
                </div>
            </div>
        }
        <div class="flex-1"></div>
        @if (has_master_audio() !== false) {
            <div
                class="text-base-content flex w-lg max-w-[50%] items-center space-x-2 px-4 py-2"
            >
                <button icon matRipple mute (click)="toggleMute()">
                    <icon>{{ volume_icon() }}</icon>
                </button>
                <mat-slider class="flex-1" [class.opacity-50]="system()?.mute">
                    <input
                        matSliderThumb
                        [ngModel]="system()?.volume || 0"
                        (ngModelChange)="setVolume($event)"
                /></mat-slider>
                <span volume-level class="w-12 text-right tabular-nums">
                    {{ system()?.volume || 0 }}%
                </span>
            </div>
        }
    `,
    styles: [
        `
            :host {
                display: flex;
                align-items: center;
                height: 3.5rem;
                overflow: hidden;
            }
        `,
    ],
    imports: [
        BindingDirective,
        MatSliderModule,
        FormsModule,
        MatRippleModule,
        IconComponent,
        DurationPipe,
        TranslatePipe,
    ],
})
export class ControlStatusBarComponent {
    private _state = inject(ControlStateService);

    /** Details of the active system */
    public readonly system = this._state.system;
    public readonly has_master_audio = this._state.has_master_audio;

    public readonly capture_mod = computed(() => this._state.capture_list()[0]);

    public readonly volume_icon = computed(() => {
        const sys = this.system();
        if (sys?.mute) return 'volume_off';
        return sys?.volume > 0 ? 'volume_up' : 'volume_mute';
    });

    public rec_status: string;
    public rec_title: string;
    public rec_remaining: number;
    public rec_next: number;

    /** Set the master volume. Moving the slider while muted also unmutes. */
    public readonly setVolume = (v: number) => {
        if (this.system()?.mute) this._state.setMute(false);
        this._state.setVolume(v);
    };
    public readonly toggleMute = () => {
        const sys = this.system();
        this._state.setMute(!sys?.mute);
    };

    public get id() {
        return this._state.id;
    }
}
